let state;try{state=JSON.parse(localStorage.getItem(STORE));if(state?.schema!==2)state=seed();}catch{state=seed();}
let page='explore',selected='e1',query='',category='Tất cả',mineFilter='all',peopleFilter='all',accountQuery='',phaseChoice='checkin',toastTimer;
const current=()=>state.users.find(x=>x.id===state.uid)||state.users[0];
const event=()=>state.events.find(e=>e.id===selected)||state.events[0];
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{}}
function fmt(v,withYear=false){if(!v)return '';return new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',...(withYear?{year:'numeric'}:{})}).format(new Date(v));}
const time=v=>v?.slice(11,16)||'';
const stamp=()=>new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'});
// DEFERRED ORIGINAL (preserved; superseded by scope 2026-11-03): const modeName=e=>e.mode==='double'?'2 lần · Check-in & check-out':'1 lần điểm danh';
const modeName=e=>'1 lần điểm danh đầu vào';
function entries(e,status){return Object.entries(e.regs).filter(([,r])=>!status||r.status===status);}
const registered=e=>entries(e,'Registered');
const waiting=e=>entries(e,'Waitlisted').sort((a,b)=>a[1].order-b[1].order);
const complete=(e,r)=>!!r?.checkin&&(e.mode==='single'||!!r.checkout);
function metrics(e){const rows=registered(e);const n=rows.length,done=rows.filter(([,r])=>complete(e,r)).length,partial=rows.filter(([,r])=>r.checkin&&!complete(e,r)).length;return {n,done,partial,notStarted:n-done-partial,waiting:waiting(e).length,rate:n?Math.round(done/n*100):null};}
const initials=name=>name.split(' ').slice(-2).map(x=>x[0]).join('');
function badge(label,color=''){return `<span class="badge ${color}">${esc(label)}</span>`;}
function regBadge(e,r,uid=state.uid){if(!r)return '';return r.status==='Registered'?badge('Đã đăng ký'):r.status==='Waitlisted'?badge('Đang chờ · #'+(waiting(e).findIndex(([id])=>id===uid)+1),'amber'):badge('Đã hủy','gray');}
function attBadge(e,r){if(!r||r.status!=='Registered')return badge('—','gray');return complete(e,r)?badge('Đã hoàn tất'):r.checkin?badge('Đã check-in · Thiếu check-out','amber'):badge(e.finished?'Vắng mặt':'Chưa điểm danh','gray');}
// DEFERRED ORIGINAL (preserved; superseded by scope 2026-11-03): function eligible(e,u=current()){return (e.audience==='all'||e.audience===u.faculty)&&(e.year==='all'||e.year===u.year);}
function eligible(e,u=current()){return (!e.departments?.length||e.departments.includes(u.faculty))&&(!e.studyYears?.length||e.studyYears.includes(String(u.year)));}
function registrationOpen(e){const now=new Date();return e.published&&!e.finished&&now>=new Date(e.openAt)&&now<new Date(e.closeAt)&&now<new Date(e.startAt);}
const canCancel=e=>!e.finished&&new Date()<new Date(e.startAt);
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function closeModal(){$('#modal').close();}
function modal(title,body,action,label='Xác nhận',ico='info'){$('#modalBody').innerHTML=`<div class="modal-icon">${icon(ico)}</div><h2 id="modalTitle">${esc(title)}</h2>${body}<div class="form-error" id="modalError" role="alert"></div><div class="modal-actions"><button onclick="closeModal()">Quay lại</button><button class="primary" id="modalConfirm">${esc(label)}</button></div>`;$('#modalConfirm').onclick=()=>{try{if(action()!==false)closeModal();}catch(err){$('#modalError').textContent=err.message;}};$('#modal').showModal();}
function error(text){$('#modalError').textContent=text;return false;}
const menu={student:[['explore','grid','Khám phá sự kiện'],['mine','calendar','Sự kiện của tôi'],['scan','qr','Điểm danh QR']],organizer:[['manage','grid','Sự kiện quản lý'],['create','plus','Tạo sự kiện'],['participants','users','Người tham gia'],['attendance','qr','Điểm danh'],['report','chart','Báo cáo']],admin:[['accounts','users','Quản lý tài khoản'],['account-create','plus','Cấp tài khoản']]};
function brand(){return '<a class="brand" href="#" onclick="goHome();return false"><span class="brand-mark">ce</span><span>campus<em>events</em></span></a>';}
function nav(mobile=false){return menu[state.role].map(([p,ico,label])=>`<button class="${page===p?'active':''}" onclick="go('${p}')">${icon(ico)}<span>${mobile&&p==='explore'?'Khám phá':mobile&&p==='mine'?'Của tôi':mobile&&p==='scan'?'Quét QR':label}</span>${!mobile&&p==='mine'?`<span class="nav-count">${state.events.filter(e=>['Registered','Waitlisted'].includes(e.regs[state.uid]?.status)).length}</span>`:''}</button>`).join('');}
function shell(content){const u=current(),role=state.role;const title=menu[role].find(x=>x[0]===page)?.[2]||'Chi tiết sự kiện';return `<aside class="sidebar ${role}">${brand()}<div class="school">KHÔNG GIAN SỰ KIỆN SINH VIÊN</div><div class="nav-caption">${role==='student'?'KHÔNG GIAN CỦA BẠN':role==='organizer'?'KHÔNG GIAN TỔ CHỨC':'QUẢN TRỊ HỆ THỐNG'}</div><nav class="nav">${nav()}</nav><div class="sidebar-bottom"><div class="side-note"><strong>Mọi lượt tham gia đều rõ ràng.</strong>Theo dõi đăng ký, điểm danh và kết quả trong cùng một không gian.</div><div class="profile"><span class="avatar">${initials(u.name)}</span><div><b>${esc(u.name)}</b><small>${human[role]}</small></div></div></div></aside><div class="workspace ${role==='student'?'student-workspace':''}"><header class="topbar"><div class="breadcrumb">${human[role]}<span>/</span>${esc(title)}</div><div class="top-actions"><span class="demo-pill">Bản tương tác mẫu</span><select class="role-select" aria-label="Xem theo vai trò" onchange="setRole(this.value)">${Object.entries(human).map(([id,name])=>`<option value="${id}" ${id===role?'selected':''}>${name}</option>`).join('')}</select><span class="avatar">${initials(u.name)}</span><button class="ghost logout" title="Đăng xuất" aria-label="Đăng xuất" onclick="logout()">${icon('logout')}</button></div></header><main>${content}</main><footer><b>Campus Events</b><span>Dữ liệu minh họa · ${new Date().getFullYear()}</span></footer></div>${role==='student'?`<nav class="mobile-nav" aria-label="Điều hướng sinh viên">${nav(true)}</nav>`:''}`;}
function goHome(){go(menu[state.role][0][0]);}
function setRole(role){state.role=role;state.uid=role==='student'?'s1':role==='organizer'?'o1':'a1';state.authenticated=true;selected='e1';query='';category='Tất cả';peopleFilter='all';page=menu[role][0][0];persist();render();}
function go(p){page=p;query='';category='Tất cả';peopleFilter='all';render();window.scrollTo(0,0);}
function openEvent(id,destination='detail'){selected=id;phaseChoice='checkin';go(destination);}
function head(title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">CAMPUS EVENTS</div><h1>${title}</h1><p>${sub}</p></div>${action?`<div class="actions">${action}</div>`:''}</div>`;}
function picker(){const choices=state.events.filter(e=>e.owner===state.uid||state.role!=='organizer');if(!choices.some(e=>e.id===selected))selected=choices[0]?.id||'e1';return `<select class="event-select" aria-label="Chọn sự kiện" onchange="selected=this.value;phaseChoice='checkin';render()">${choices.map(e=>`<option value="${e.id}" ${e.id===selected?'selected':''}>${esc(e.title)}</option>`).join('')}</select>`;}
function empty(title,sub,action=''){return `<div class="empty">${icon('calendar')}<h3>${title}</h3><p>${sub}</p>${action}</div>`;}
// DEFERRED ORIGINAL: function eventCard(e){const r=e.regs[state.uid],m=metrics(e);return `<article class="card"><div class="poster ${e.color}"><small>${e.kicker}</small><strong>${e.poster}</strong><span class="poster-tag">${fmt(e.startAt)}</span></div><div class="card-body"><span class="category">${esc(e.category)}</span><h3>${esc(e.title)}</h3><div class="meta">${icon('clock')}${fmt(e.startAt,true)} · ${time(e.startAt)}<br>${icon('pin')}${esc(e.place)}</div><div class="mode-label">${icon(e.mode==='double'?'repeat':'check')}${modeName(e)}</div>${page==='mine'&&r?.status==='Registered'?`<div class="att-chip"><span>Điểm danh</span>${attBadge(e,r)}</div>`:''}<div class="card-foot">${regBadge(e,r)||badge(e.finished?'Đã kết thúc':m.n>=e.capacity?'Đã đủ chỗ':`Còn ${e.capacity-m.n} chỗ`,e.finished?'gray':m.n>=e.capacity?'amber':'blue')}<button class="text-button" onclick="openEvent('${e.id}')">Chi tiết ${icon('arrow')}</button></div></div></article>`;}
function eventCard(e){const r=e.regs[state.uid],m=metrics(e);return `<article class="card"><div class="poster ${e.color}"><small>${e.kicker}</small><strong>${e.poster}</strong><span class="poster-tag">${fmt(e.startAt)}</span></div><div class="card-body"><span class="category">${esc(e.category)}</span><h3>${esc(e.title)}</h3><div class="meta">${icon('clock')}${fmt(e.startAt,true)} · ${time(e.startAt)}<br>${icon('pin')}${esc(e.place)}</div><div class="mode-label">${icon(false /* DEFERRED: check-out */?'repeat':'check')}${modeName(e)}</div>${page==='mine'&&r?.status==='Registered'?`<div class="att-chip"><span>Điểm danh</span>${attBadge(e,r)}</div>`:''}<div class="card-foot">${regBadge(e,r)||badge(e.finished?'Đã kết thúc':m.n>=e.capacity?'Đã đủ chỗ':`Còn ${e.capacity-m.n} chỗ`,e.finished?'gray':m.n>=e.capacity?'amber':'blue')}<button class="text-button" onclick="openEvent('${e.id}')">Chi tiết ${icon('arrow')}</button></div></div></article>`;}
// DEFERRED ORIGINAL: function filteredEvents(){return state.events.filter(e=>e.published&&(page!=='mine'||e.regs[state.uid])&&(mineFilter==='all'||page!=='mine'||e.regs[state.uid]?.status===mineFilter)&&(category==='Tất cả'||e.category===category)&&e.title.toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi')));}
function filteredEvents(){return state.events.filter(e=>e.published&&(page!=='mine'||e.regs[state.uid])&&(mineFilter==='all'||page!=='mine'||e.regs[state.uid]?.status===mineFilter)&&true /* DEFERRED: category filter */&&e.title.toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi')));}
function fillCards(){const list=filteredEvents();$('#cards').innerHTML=list.length?list.map(eventCard).join(''):empty('Chưa có sự kiện phù hợp','Thử đổi từ khóa hoặc xem các sự kiện khác.',`<button onclick="go('explore')">Khám phá sự kiện ${icon('arrow')}</button>`);$('#resultCount').textContent=`${list.length} sự kiện`;}
function explore(mine=false){return head(mine?'Sự kiện của tôi':'Khám phá sự kiện',mine?'Lịch hẹn, trạng thái đăng ký và từng lượt điểm danh của bạn.':'Tìm những hoạt động bạn muốn tham gia tại trường.')+(!mine?`<section class="hero"><div><div class="eyebrow">KHÁM PHÁ · HỌC HỎI · KẾT NỐI</div><h2>Bước ra khỏi lớp học.<br>Thêm một trải nghiệm mới.</h2><p>Seminar, workshop và những cuộc gặp gỡ dành cho cộng đồng sinh viên.</p><button class="primary" onclick="$('#eventSearch').focus()">Tìm sự kiện của bạn ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="ticket"><small>YOUR CAMPUS. YOUR MOMENT.</small><strong>LET’S<br>CONNECT.</strong><div class="ticket-line"><span>ADMIT ONE</span><span>✦ 2026</span></div></div><span class="star">✦</span></div></section>`:'')+`<div class="section-head"><div><h2>${mine?'Lịch hẹn của bạn':'Sự kiện tại trường'}</h2><p id="resultCount"></p></div>${mine?`<select class="role-select" aria-label="Lọc đăng ký" onchange="mineFilter=this.value;fillCards()"><option value="all" ${mineFilter==='all'?'selected':''}>Tất cả trạng thái</option><option value="Registered" ${mineFilter==='Registered'?'selected':''}>Đã đăng ký</option><option value="Waitlisted" ${mineFilter==='Waitlisted'?'selected':''}>Đang chờ</option><option value="Cancelled" ${mineFilter==='Cancelled'?'selected':''}>Đã hủy</option></select>`:'<span class="muted small-text">Lịch hoạt động 2026</span>'}</div><div class="toolbar"><label class="search">${icon('search')}<input id="eventSearch" aria-label="Tìm sự kiện" placeholder="Tìm tên sự kiện bạn quan tâm..." value="${esc(query)}" oninput="query=this.value;fillCards()"></label><div class="chips">${['Tất cả','Học thuật','Nghề nghiệp','Văn hóa','Thể thao'].map(c=>`<button class="${category===c?'active':''}" onclick="category='${c}';render()">${c}</button>`).join('')}</div></div><div class="grid" id="cards"></div>`;}
