function attendance(){const pick=picker(),e=event();if(e.mode==='single')phaseChoice='checkin';const currentLabel=e.phase?(e.mode==='single'?'Lượt điểm danh':e.phase==='checkin'?'Check-in':'Check-out'):'';return head('Quản lý điểm danh','Mở QR theo từng lượt và bổ sung kết quả khi cần.',pick)+stats(e)+`<div class="split equal gap-bottom"><section class="panel"><div class="att-top"><div><h3>Phiên điểm danh QR</h3><p class="small-text muted">${modeName(e)}</p></div>${badge(e.phase?'Đang mở '+currentLabel:'Phiên đã đóng',e.phase?'blue':'gray')}</div>${false /* DEFERRED: check-out */?`<div class="phase-bar"><button class="phase-choice ${phaseChoice==='checkin'?'active':''}" onclick="phaseChoice='checkin';render()"><span class="phase-dot"></span><b>01 · Check-in</b><span>Ghi nhận lúc sinh viên vào</span></button><button class="phase-choice ${phaseChoice==='checkout'?'active':''}" onclick="phaseChoice='checkout';render()"><span class="phase-dot"></span><b>02 · Check-out</b><span>Ghi nhận lúc sinh viên ra</span></button></div>`:'<div class="notice">Sinh viên quét QR một lần để hoàn tất điểm danh.</div>'}<button class="primary block" onclick="togglePhase()" ${!e.published?'disabled':''}>${icon(e.phase===phaseChoice?'lock':'qr')} ${e.phase===phaseChoice?'Đóng':e.phase?'Chuyển sang':'Mở'} ${e.mode==='single'?'lượt điểm danh':phaseChoice==='checkin'?'check-in':'check-out'}</button><p class="small-text muted gap-top">${e.phase&&e.phase!==phaseChoice?'Khi chuyển lượt, QR cũ sẽ hết hiệu lực.':'Chỉ sinh viên đăng ký chính thức được ghi nhận.'}</p>${!e.published?'<div class="notice warn">Công bố sự kiện trước khi mở điểm danh.</div>':''}</section><section class="qr-panel">${e.phase?`<span class="eyebrow">${currentLabel}</span><h3>${esc(e.title)}</h3><div class="qr-wrap">${qrPattern(e,e.phase)}<span class="qr-overlay">QR MẪU</span></div><div class="qr-caption">Mã minh họa cho lượt ${currentLabel.toLowerCase()}<br>Chuyển sang vai trò Sinh viên để quét thử.</div>`:`<div class="qr-empty">${icon('qr')}</div><h3>Chưa có QR đang mở</h3><p class="muted small-text gap-top">Chọn lượt rồi bấm mở điểm danh.</p>`}</section></div><div class="section-head"><div><h2>Kết quả theo từng sinh viên</h2><p>${false /* DEFERRED: check-out */?'Thiếu check-out được giữ riêng với người chưa điểm danh.':'Một lượt hợp lệ tương ứng một người hoàn tất.'}</p></div></div>${participantTable(e,true)}`;}
