function participants(){const pick=picker(),e=event(),m=metrics(e);return head('Danh sách người tham gia','Theo dõi danh sách chính thức, thứ tự chờ và kết quả điểm danh.',pick)+`<div class="notice">${m.n} đăng ký chính thức · ${m.waiting} người đang chờ · ${modeName(e)}</div>${participantTable(e)}`;}
