function scan(){const choices=state.events.filter(e=>e.published&&e.regs[state.uid]?.status==='Registered');if(!choices.length)return head('Điểm danh bằng QR','Quét QR do người tổ chức hiển thị.')+`<section class="panel">${empty('Bạn chưa có đăng ký chính thức','Người đang trong danh sách chờ chưa thể điểm danh.',`<button class="primary" onclick="go('explore')">Khám phá sự kiện</button>`)}</section>`;if(!choices.some(e=>e.id===selected))selected=choices[0].id;const e=event(),r=e.regs[state.uid],label=e.phase?(e.mode==='single'?'Điểm danh một lần':e.phase==='checkin'?'Check-in':'Check-out'):'';return head('Điểm danh bằng QR','Kết quả được ghi nhận riêng theo từng lượt của sự kiện.')+`<div class="scan-shell"><section class="panel"><label class="field">Sự kiện đã đăng ký<select aria-label="Sự kiện quét QR" onchange="selected=this.value;render()">${choices.map(e=>`<option value="${e.id}" ${e.id===selected?'selected':''}>${esc(e.title)}</option>`).join('')}</select></label><div class="att-top"><span class="small-text muted">${modeName(e)}</span>${attBadge(e,r)}</div><div class="scan-view"><div class="scan-target">${icon('qr')}</div><span class="scan-hint">Khung quét minh họa · Không mở camera</span></div>${e.phase?`<div class="notice success">Người tổ chức đang mở <b>${label}</b>.</div>`:'<div class="notice warn">Chưa có lượt QR đang mở. Bạn có thể xem trạng thái hoặc liên hệ người tổ chức.</div>'}<button class="primary block" onclick="scanCurrent()">${icon('camera')} Quét thử mã hiện tại</button><button class="ghost block gap-top" onclick="scanHelp()">Không quét được? Xem hướng dẫn</button><div class="section-head"><h3>Tiến độ của bạn</h3></div>${timeline(e,r)}</section></div>`;}
function scanCurrent(){const e=event(),r=e.regs[state.uid];if(r?.status!=='Registered')return toast('Cần đăng ký chính thức trước khi điểm danh.');if(!e.phase)return modal('QR chưa có hiệu lực','<p>Phiên điểm danh chưa được mở hoặc đã đóng. Hãy kiểm tra mã đang hiển thị hoặc liên hệ người tổ chức để được xác minh, bổ sung.</p>',()=>true,'Đã hiểu','lock');const phase=e.phase;if(phase==='checkout'&&!r.checkin)return modal('Bạn còn thiếu check-in','<p>Hệ thống chưa có lượt check-in của bạn. Hãy liên hệ người tổ chức để được kiểm tra và bổ sung trước khi hoàn tất check-out.</p>',()=>true,'Đã hiểu','info');if(r[phase])return toast(`Lượt ${e.mode==='single'?'điểm danh':phase==='checkin'?'check-in':'check-out'} đã được ghi nhận lúc ${r[phase+'At']}.`);r[phase]=true;r[phase+'At']=stamp();r.history.push({at:new Date().toISOString(),method:'QR mẫu',phase,by:state.uid});persist();render();modal(complete(e,r)?'Bạn đã hoàn tất điểm danh':'Check-in thành công',`<p><b>${esc(e.title)}</b></p><div class="notice success">${complete(e,r)?'Đã đủ các lượt theo yêu cầu. Bạn được ghi nhận tham dự.':'Đã ghi nhận lượt vào. Bạn còn cần check-out khi kết thúc sự kiện.'}</div>${timeline(e,r)}`,()=>true,'Đóng','check');}
function scanHelp(){modal('Bổ sung lượt bị thiếu','<p>Nếu đến muộn, thiết bị gặp lỗi hoặc mã đã đóng, hãy báo MSSV và lượt còn thiếu cho người tổ chức. Người tổ chức sẽ xác minh trước khi cập nhật thủ công.</p>',()=>true,'Đã hiểu','info');}
