function csvCell(v){return '"'+String(v??'').replaceAll('"','""')+'"';}
// DEFERRED ORIGINAL (preserved; superseded by scope 2026-11-03): function csvData(e,reportMode=false){const m=metrics(e),rows=[];if(reportMode){rows.push(['Sự kiện',e.title],['Chế độ điểm danh',modeName(e)],['Đăng ký chính thức',m.n],['Hoàn tất',m.done],['Thiếu check-out',m.partial],['Chưa điểm danh',m.notStarted],['Tỷ lệ hoàn tất',m.rate===null?'Không áp dụng':m.rate+'%'],[]);}rows.push(['MSSV','Họ tên','Trạng thái đăng ký','Vị trí chờ','Check-in','Check-out','Kết quả']);for(const [uid,r] of entries(e)){const u=state.users.find(x=>x.id===uid);rows.push([u.studentId,u.name,r.status,r.status==='Waitlisted'?waiting(e).findIndex(([id])=>id===uid)+1:'',r.checkinAt||'',e.mode==='double'?(r.checkoutAt||''):'Không áp dụng',r.status!=='Registered'?'Không áp dụng':complete(e,r)?'Hoàn tất':r.checkin?'Thiếu check-out':e.finished?'Vắng mặt':'Chưa điểm danh']);}return rows.map(row=>row.map(csvCell).join(',')).join('\r\n');}
function csvData(e,reportMode=false){const m=metrics(e),rows=[];if(reportMode)rows.push(['Sự kiện',e.title],['Đăng ký chính thức',m.n],['Tham dự',m.done],['Vắng mặt',e.finished?m.n-m.done:'Chưa kết thúc'],['Tỷ lệ',m.rate===null?'Không áp dụng':m.rate+'%'],[]);rows.push(['MSSV','Họ tên','Trạng thái đăng ký','Vị trí chờ','Điểm danh đầu vào','Kết quả']);for(const [uid,r] of entries(e)){const u=state.users.find(x=>x.id===uid);rows.push([u.studentId,u.name,r.status,r.status==='Waitlisted'?waiting(e).findIndex(([id])=>id===uid)+1:'',r.checkinAt||'',r.status!=='Registered'?'Không áp dụng':r.checkin?'Có mặt':e.finished?'Vắng mặt':'Chưa ghi nhận']);}return rows.map(row=>row.map(csvCell).join(',')).join('\r\n');}
function exportCSV(){const e=event(),data='\ufeff'+csvData(e,page==='report');const url=URL.createObjectURL(new Blob([data],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${page==='report'?'bao-cao':'danh-sach'}-${e.id}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất CSV theo dữ liệu hiện tại của sự kiện.');}
function accountView(){return head('Quản lý tài khoản','Tra cứu tài khoản, trạng thái truy cập và vai trò.',`<button class="primary" onclick="go('account-create')">${icon('plus')} Cấp tài khoản</button>`)+`<section class="panel"><div class="toolbar"><label class="search">${icon('search')}<input aria-label="Tìm tài khoản" placeholder="Tìm họ tên, email hoặc MSSV..." oninput="filterRows(this.value)"></label><button class="small" onclick="resetDemo()">${icon('reset')} Khôi phục dữ liệu mẫu</button></div><div class="table-wrap"><table><thead><tr><th>Tài khoản</th><th>Vai trò</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${state.users.map(u=>`<tr class="person-row"><td><div class="person-cell"><span class="avatar ${u.role==='organizer'?'green':''}">${initials(u.name)}</span><div><strong>${esc(u.name)}</strong><small>${esc(u.email)}${u.studentId?' · '+esc(u.studentId):''}</small></div></div></td><td>${human[u.role]}</td><td>${badge(u.locked?'Đã khóa':'Hoạt động',u.locked?'gray':'')}</td><td><div class="row-actions"><button class="small" onclick="accountAction('${u.id}','lock')">${u.locked?'Mở khóa':'Khóa'}</button><button class="small" onclick="accountAction('${u.id}','role')">Đổi vai trò</button></div></td></tr>`).join('')}</tbody></table></div></section>`;}
// DEFERRED ORIGINAL (preserved; superseded by scope 2026-11-03): function accountAction(uid,action){const u=state.users.find(x=>x.id===uid);modal(action==='role'?'Thay đổi vai trò':u.locked?'Mở khóa tài khoản':'Khóa tài khoản',`<p><b>${esc(u.name)}</b><br>${esc(u.email)}</p>${action==='role'?`<label class="field">Vai trò mới<select id="nextRole">${Object.entries(human).map(([v,n])=>`<option value="${v}" ${u.role===v?'selected':''}>${n}</option>`).join('')}</select></label>`:''}<label class="field">Lý do<textarea id="accountReason" rows="3"></textarea></label>`,()=>{if(!$('#accountReason').value.trim())return error('Vui lòng nhập lý do.');if(action==='role')u.role=$('#nextRole').value;else u.locked=!u.locked;if(uid===state.uid){persist();logout();}else{persist();render();}toast('Đã cập nhật tài khoản mẫu.');},'Lưu thay đổi','shield');}
function accountAction(uid,action){const u=state.users.find(x=>x.id===uid);if(uid===state.uid)return toast('Không được tự khóa hoặc tự đổi vai trò.');modal(action==='role'?'Đổi vai trò':'Khóa / mở khóa',`<p>${esc(u.name)}</p>${action==='role'?`<label class="field">Vai trò<select id="nextRole">${Object.entries(human).map(([v,n])=>`<option value="${v}" ${u.role===v?'selected':''}>${n}</option>`).join('')}</select></label>`:''}<label class="field">Lý do<textarea id="accountReason"></textarea></label>`,()=>{const reason=$('#accountReason').value.trim(),role=action==='role'?$('#nextRole').value:u.role,locking=action==='lock'&&!u.locked;if(!reason)return error('Cần lý do.');if(u.role==='admin'&&!u.locked&&(locking||role!=='admin')&&!state.users.some(x=>x.id!==uid&&x.role==='admin'&&!x.locked))return error('Phải giữ ít nhất một Admin đang hoạt động.');if(role==='student'&&(!u.studentId||!u.year||!u.faculty))return error('Cần hồ sơ sinh viên trước khi đổi vai trò.');if(u.role==='organizer'&&(locking||role!=='organizer')&&state.events.some(e=>e.owner===uid&&(!e.published||!e.finished)))return error('Người tổ chức còn sự kiện chưa xử lý.');u.history??=[];u.history.push({at:new Date().toISOString(),reason,action,before:{role:u.role,locked:u.locked}});if(action==='role')u.role=role;else u.locked=!u.locked;persist();render();},'Lưu','shield');}
function accountCreate(){return head('Cấp tài khoản người tổ chức','Tạo tài khoản mẫu cho người được phân công phụ trách sự kiện.')+`<form id="accountForm" class="panel" style="max-width:720px"><h3 class="form-title">${icon('users')} Thông tin người tổ chức</h3>${field('Họ và tên','name')}${field('Email','email','','email')}${field('Đơn vị tổ chức','faculty')}<div class="form-error" id="accountFormError" role="alert"></div><div class="form-footer"><span class="small-text muted">Tài khoản được cấp vai trò Người tổ chức.</span><button class="primary" type="submit">Cấp tài khoản</button></div></form>`;}
function saveAccount(form){const d=Object.fromEntries(new FormData(form));if(state.users.some(u=>u.email.toLowerCase()===d.email.trim().toLowerCase())){$('#accountFormError').textContent='Email đã tồn tại. Hãy tra cứu tài khoản để điều chỉnh vai trò.';return;}state.users.push({id:'u'+Date.now(),name:d.name.trim(),email:d.email.trim(),faculty:d.faculty.trim(),role:'organizer',locked:false});persist();go('accounts');toast('Đã tạo tài khoản Người tổ chức trong dữ liệu mẫu.');}
function logout(){state.authenticated=false;page='login';persist();render();window.scrollTo(0,0);}
function auth(signup=false){return `<div class="auth-shell"><section class="auth-art">${brand()}<div><h1>Những trải nghiệm<br>bắt đầu từ đây.</h1><p>Một không gian cho sự kiện, đăng ký và từng lượt tham gia tại trường.</p></div><small>Campus Events · Bản tương tác minh họa</small></section><section class="auth-content"><div class="auth-box"><div class="eyebrow">${signup?'TÀI KHOẢN SINH VIÊN':'CHÀO MỪNG TRỞ LẠI'}</div><h1>${signup?'Đăng ký tài khoản':'Đăng nhập'}</h1><p>${signup?'Tự tạo tài khoản để tìm sự kiện và theo dõi đăng ký.':'Dùng tài khoản mẫu hoặc nhập email đã tạo trong bản thử nghiệm.'}</p><form id="authForm">${signup?field('Họ và tên','name')+field('Mã số sinh viên','studentId'):''}${field('Email','email','','email')}${field('Mật khẩu mẫu','password','','password')}${signup?`<div class="form-grid"><label class="field">Khoa<select name="faculty"><option>${shortFaculty}</option><option>Khoa Kinh tế</option></select></label><label class="field">Năm học<select name="year">${[1,2,3,4,5].map(n=>`<option value="${n}">Năm ${n}</option>`).join('')}</select></label></div>`:''}<div class="form-error" id="authError" role="alert"></div><button class="primary block" type="submit">${signup?'Tạo tài khoản':'Đăng nhập bản mẫu'} ${icon('arrow')}</button></form><button class="ghost block gap-top" onclick="page='${signup?'login':'signup'}';render()">${signup?'Đã có tài khoản? Đăng nhập':'Chưa có tài khoản? Đăng ký sinh viên'}</button>${signup?'':`<div class="divider">hoặc mở nhanh tài khoản mẫu</div><div class="demo-logins">${[['student','Minh Anh · Sinh viên','Đăng ký, quét QR và xem kết quả'],['organizer','Thu Hà · Người tổ chức','Mở từng lượt QR, bổ sung điểm danh'],['admin','Quản trị viên','Quản lý tài khoản và vai trò']].map(([r,n,s])=>`<button onclick="setRole('${r}')"><span>${n}<small>${s}</small></span>${icon('arrow')}</button>`).join('')}</div>`}<p class="small-text muted gap-top">Dữ liệu chỉ lưu trên thiết bị. Không nhập mật khẩu thật; bản mẫu chưa có xác thực hoặc dịch vụ email.</p></div></section></div>`;}
function saveAuth(form){const d=Object.fromEntries(new FormData(form));if(page==='signup'){if(state.users.some(u=>u.email.toLowerCase()===d.email.trim().toLowerCase()||u.studentId&&u.studentId===d.studentId.trim())){$('#authError').textContent='Email hoặc MSSV đã tồn tại.';return;}state.users.push({id:'s'+Date.now(),name:d.name.trim(),studentId:d.studentId.trim(),email:d.email.trim(),faculty:d.faculty,year:d.year,role:'student',locked:false});persist();page='login';render();toast('Tạo tài khoản mẫu thành công. Bạn có thể đăng nhập bằng email vừa tạo.');}else{const u=state.users.find(u=>u.email.toLowerCase()===d.email.trim().toLowerCase());if(!u){$('#authError').textContent='Chưa tìm thấy email trong dữ liệu mẫu.';return;}if(u.locked){$('#authError').textContent='Tài khoản đang bị khóa.';return;}state.uid=u.id;state.role=u.role;state.authenticated=true;page=menu[u.role][0][0];persist();render();}}
function resetDemo(){modal('Khôi phục dữ liệu minh họa?','<p>Thao tác chỉ xóa các thay đổi trong bản mẫu này và khôi phục sự kiện, tài khoản ban đầu trên thiết bị.</p>',()=>{state=seed();state.role='admin';state.uid='a1';page='accounts';selected='e1';persist();render();toast('Đã khôi phục dữ liệu mẫu.');},'Khôi phục','reset');}
// DEFERRED ORIGINAL: function render(){if(!state.authenticated){$('#app').innerHTML=auth(page==='signup');$('#authForm').onsubmit=e=>{e.preventDefault();saveAuth(e.target);};return;}if(!menu[state.role])state.role='student';if(!state.events.some(e=>e.id===selected))selected=state.events[0].id;if(state.role==='organizer'&&['participants','attendance','report','edit'].includes(page)&&!state.events.some(e=>e.owner===state.uid)){ $('#app').innerHTML=shell(head('Chưa có sự kiện quản lý','Tạo sự kiện để bắt đầu quản lý đăng ký và điểm danh.')+empty('Bạn chưa phụ trách sự kiện nào','Mỗi người tổ chức chỉ xem dữ liệu sự kiện mình phụ trách.',`<button class="primary" onclick="go('create')">Tạo sự kiện</button>`));return;}const views={explore:()=>explore(),mine:()=>explore(true),detail,manage,create:()=>createForm(),edit:()=>createForm(true),participants,attendance,scan,report,accounts:accountView,'account-create':accountCreate};$('#app').innerHTML=shell((views[page]||views.explore)());if($('#cards'))fillCards();if($('#eventForm'))$('#eventForm').onsubmit=e=>{e.preventDefault();saveEvent(e.target);};if($('#accountForm'))$('#accountForm').onsubmit=e=>{e.preventDefault();saveAccount(e.target);};}
function render(){normalize();if(!state.authenticated){$('#app').innerHTML=auth(page==='signup');$('#authForm').onsubmit=e=>{e.preventDefault();saveAuth(e.target);};return;}if(!menu[state.role])state.role='student';if(!state.events.some(e=>e.id===selected))selected=state.events[0].id;if(state.role==='organizer'&&['participants','attendance','report','edit'].includes(page)&&!state.events.some(e=>e.owner===state.uid)){ $('#app').innerHTML=shell(head('Chưa có sự kiện quản lý','Tạo sự kiện để bắt đầu quản lý đăng ký và điểm danh.')+empty('Bạn chưa phụ trách sự kiện nào','Mỗi người tổ chức chỉ xem dữ liệu sự kiện mình phụ trách.',`<button class="primary" onclick="go('create')">Tạo sự kiện</button>`));return;}const views={explore:()=>explore(),mine:()=>explore(true),detail,manage,create:()=>createForm(),edit:()=>createForm(true),participants,attendance,scan,report,accounts:accountView,'account-create':accountCreate};$('#app').innerHTML=shell((views[page]||views.explore)());if($('#cards'))fillCards();if($('#eventForm'))$('#eventForm').onsubmit=e=>{e.preventDefault();saveEvent(e.target);};if($('#accountForm'))$('#accountForm').onsubmit=e=>{e.preventDefault();saveAccount(e.target);};}
function normalize(){for(const e of state.events){e.mode='single';if(!e.departments)e.departments=e.audience&&e.audience!=='all'?[e.audience]:[];if(!e.studyYears)e.studyYears=e.year&&e.year!=='all'?[String(e.year)]:[];const descriptor=Object.getOwnPropertyDescriptor(e,'finished');if(!descriptor?.get){Object.defineProperty(e,'finished',{configurable:true,enumerable:false,get(){return Date.now()>=new Date(this.endAt).getTime();},set(value){/* DEFERRED: manual end flag */}});}if(e.phase==='checkout')e.phase=null;}}

render();
setInterval(()=>{if(!document.querySelector("dialog[open]")&&!["create","edit","signup","account-create"].includes(page))render();},30000);